<template><div class="page"><div class="page-header"><div><h1 class="page-title">题库管理</h1><p class="page-description">AI题目审核通过后才进入正式题库并可用于规则组卷。</p></div><div><el-button @click="location.href=questionsApi.exportUrl"><Download/>导出Excel</el-button><el-button @click="router.push('/questions/import')"><Upload/>导入题目</el-button><el-button type="primary" @click="router.push('/generation/create')">AI出题</el-button></div></div><div class="toolbar card card-body"><el-input v-model="filters.keyword" placeholder="搜索题干" clearable style="width:230px"/><el-select v-model="filters.course" placeholder="全部课程" clearable style="width:170px"><el-option v-for="c in store.courses" :key="c.id" :label="c.name" :value="c.id"/></el-select><el-select v-model="filters.question_type" placeholder="全部题型" clearable style="width:140px"><el-option v-for="x in types" :key="x.value" :label="x.label" :value="x.value"/></el-select><el-select v-model="filters.difficulty" placeholder="全部难度" clearable style="width:120px"><el-option v-for="x in ['简单','较易','中等','较难','困难']" :key="x" :label="x" :value="x"/></el-select><el-select v-model="filters.review_status" placeholder="审核状态" clearable style="width:130px"><el-option v-for="x in ['PENDING','APPROVED','NEEDS_REVISION','REJECTED']" :key="x" :label="x" :value="x"/></el-select><el-button @click="load">查询</el-button></div><div class="batch" v-if="selected.length"><span>已选择 {{selected.length}} 道题</span><el-button size="small" type="success" @click="batch('approve')">批量通过</el-button><el-button size="small" type="danger" plain @click="batch('delete')">批量删除</el-button></div><div class="card"><PageState :loading="loading" :empty="!items.length" empty-text="当前筛选条件下没有题目。"><el-table :data="items" @selection-change="x=>selected=x"><el-table-column type="selection" width="46"/><el-table-column prop="id" label="编号" width="75"/><el-table-column prop="stem" label="题目预览" min-width="300" show-overflow-tooltip/><el-table-column prop="question_type" label="题型" width="115"/><el-table-column prop="course_name" label="课程" width="130"/><el-table-column prop="knowledge_point_name" label="知识点" width="130" show-overflow-tooltip/><el-table-column prop="difficulty" label="难度" width="75"/><el-table-column prop="score" label="分值" width="65"/><el-table-column label="来源" width="80"><template #default="s"><el-tag size="small" type="info">{{s.row.source_type}}</el-tag></template></el-table-column><el-table-column label="审核状态" width="105"><template #default="s"><StatusTag :value="s.row.review_status"/></template></el-table-column><el-table-column prop="use_count" label="使用" width="65"/><el-table-column label="操作" width="210" fixed="right"><template #default="s"><el-button link type="primary" @click="router.push(`/questions/${s.row.id}`)">查看</el-button><el-button v-if="s.row.review_status!=='APPROVED'" link type="success" @click="approve(s.row)">通过</el-button><el-button link @click="favorite(s.row)">{{s.row.is_favorite?'取消收藏':'收藏'}}</el-button><el-button link type="danger" @click="remove(s.row)">删除</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="prev,pager,next,total" @current-change="load"/></PageState></div></div></template>
<script setup>import{ref,reactive,onMounted}from'vue';import{useRouter,useRoute}from'vue-router';import{ElMessage,ElMessageBox}from'element-plus';import{questionsApi}from'../../api';import{useAppStore}from'../../stores/app';import PageState from'../../components/PageState.vue';import StatusTag from'../../components/StatusTag.vue';const router=useRouter(),route=useRoute(),store=useAppStore(),items=ref([]),total=ref(0),page=ref(1),loading=ref(false),selected=ref([]),filters=reactive({keyword:'',course:'',question_type:'',difficulty:'',review_status:route.query.review_status||''}),types=[['single_choice','单项选择题'],['multiple_choice','多项选择题'],['judge','判断题'],['fill_blank','填空题'],['short_answer','简答题'],['essay','论述题'],['calculation','计算题'],['programming','编程题'],['case_analysis','案例分析题']].map(([value,label])=>({value,label}));const load=async()=>{loading.value=true;try{const d=await questionsApi.list({...filters,page:page.value});items.value=d.items;total.value=d.total}finally{loading.value=false}};const approve=async x=>{await questionsApi.approve(x.id);ElMessage.success('题目已通过');load()};const favorite=async x=>{await questionsApi.favorite(x.id);load()};const remove=async x=>{await ElMessageBox.confirm('删除采用软删除，是否继续？','删除题目',{type:'warning'});await questionsApi.remove(x.id);load()};const batch=async action=>{await questionsApi.batch({ids:selected.value.map(x=>x.id),action});ElMessage.success('批量操作完成');load()};onMounted(()=>{store.loadCourses();load()})</script><style scoped>.batch{padding:10px 16px;margin-bottom:10px;background:#eaf3ff;border-radius:8px;display:flex;align-items:center;gap:10px}</style>
